const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Lower Mississippi River region
  const geometry = ee.Geometry.Polygon([
    [-91.5, 30.0],  // Southwest (Louisiana/Mississippi border area)
    [-90.0, 30.0],  // Southeast
    [-90.0, 32.0],  // Northeast
    [-91.5, 32.0],  // Northwest
    [-91.5, 30.0]   // Close polygon
  ]);

  // 2. Define date ranges (±3 days to account for possible missing data)
  const date1_start = '2019-12-01';
  const date1_end = '2019-12-07';
  const date2_start = '2020-01-30';
  const date2_end = '2020-02-05';

  // 3. Function to get water mask from Sentinel-1
  function getWaterMaskS1(startDate, endDate) {
    let coll = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', 'DESCENDING'));  // Consistent pass

    // Check if collection is empty
    let collSize = coll.size().getInfo();
    console.log(`Images found: ${collSize}`);

    if (collSize === 0) {
      return null;
    }

    // Create composite (mosaic)
    let image = coll.mosaic().select('VV');

    // Convert to dB and create water mask (water typically < -18 dB)
    let db = ee.Image(10).multiply(image.log10());
    let waterMask = db.lt(-18);  // Water pixels = 1

    return waterMask;
  }

  // 4. Try to get water masks for both dates
  let waterMask1 = getWaterMaskS1(date1_start, date1_end);
  let waterMask2 = getWaterMaskS1(date2_start, date2_end);

  // 5. Check for empty collections
  if (!waterMask1 || !waterMask2) {
    console.log("Date1 water mask:", waterMask1 ? "OK" : "Null");
    console.log("Date2 water mask:", waterMask2 ? "OK" : "Null");

    // Try fallback with Sentinel-2 NDWI
    console.log("Trying Sentinel-2 fallback...");

    function getWaterMaskS2(startDate, endDate) {
      let coll = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(geometry)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

      let collSize = coll.size().getInfo();
      console.log(`S2 Images found: ${collSize}`);

      if (collSize === 0) {
        return null;
      }

      // Create median composite and calculate NDWI
      let image = coll.median();
      let ndwi = image.normalizedDifference(['B3', 'B8']);  // (Green - NIR)/(Green + NIR)

      // Water mask: NDWI > 0.0
      let waterMask = ndwi.gt(0.0);

      return waterMask;
    }

    waterMask1 = waterMask1 || getWaterMaskS2(date1_start, date1_end);
    waterMask2 = waterMask2 || getWaterMaskS2(date2_start, date2_end);

    if (!waterMask1 || !waterMask2) {
      console.log("C1: Empty collection for one or both dates");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 6. Calculate water area for each date
  function calculateWaterArea(waterMask, dateLabel) {
    // Calculate area in km²
    let areaImage = waterMask.multiply(ee.Image.pixelArea()).divide(1e6);  // km²

    let stats = areaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 1000,  // 1km scale for efficiency
      maxPixels: 1e9
    });

    let area = stats.getNumber('VV' || 'nd').getInfo();
    let count = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).getNumber('VV' || 'nd').getInfo();

    console.log(`${dateLabel}: Water area = ${area.toFixed(2)} km², Valid pixels = ${count}`);

    return {area: area, count: count};
  }

  let result1 = calculateWaterArea(waterMask1, "Dec 2019");
  let result2 = calculateWaterArea(waterMask2, "Feb 2020");

  // 7. Check for no valid pixels (C2)
  if (result1.count === 0 || result2.count === 0) {
    console.log(`C2: No valid water pixels (Counts: ${result1.count}, ${result2.count})`);
    console.log("<answer>C2</answer>");
    return;
  }

  // 8. Check for calculation failures (C3)
  if (result1.area === null || result2.area === null || 
      isNaN(result1.area) || isNaN(result2.area) ||
      result1.area < 0 || result2.area < 0) {
    console.log(`C3: Invalid area calculation (${result1.area}, ${result2.area})`);
    console.log("<answer>C3</answer>");
    return;
  }

  // 9. Compare and output result
  console.log(`Area change: ${result2.area - result1.area} km²`);
  console.log(`Percent change: ${((result2.area - result1.area) / result1.area * 100).toFixed(1)}%`);

  // 10. Determine final answer
  if (result2.area > result1.area) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
